package net.civeira.phylax.features.access.oauthclient.infrastructure.repository;

import java.util.Iterator;
import java.util.List;
import java.util.function.BiFunction;

import net.civeira.phylax.common.algorithms.Slider;
import net.civeira.phylax.features.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.features.access.oauthclient.domain.gateway.OauthClientCursor;
import net.civeira.phylax.features.access.oauthclient.domain.gateway.OauthClientFilter;

class OauthClientSlider extends Slider<OauthClient> {

  /**
   * @autogenerated SlideGenerator
   */
  private final OauthClientCursor cursor;

  /**
   * @autogenerated SlideGenerator
   */
  private final OauthClientFilter filter;

  /**
   * @autogenerated SlideGenerator
   */
  private final BiFunction<OauthClientFilter, OauthClientCursor, Iterator<OauthClient>> gateway;

  /**
   * @autogenerated SlideGenerator
   * @param multi
   * @param limit
   * @param gateway
   * @param filter
   * @param cursor
   */
  OauthClientSlider(final Iterator<OauthClient> multi, final int limit,
      final BiFunction<OauthClientFilter, OauthClientCursor, Iterator<OauthClient>> gateway,
      final OauthClientFilter filter, final OauthClientCursor cursor) {
    super(multi, limit);
    this.gateway = gateway;
    this.filter = filter;
    this.cursor = cursor;
  }

  /**
   * @autogenerated SlideGenerator
   * @param oauthClients
   * @param limit
   * @return
   */
  @Override
  public Iterator<OauthClient> next(List<OauthClient> oauthClients, int limit) {
    OauthClient last = oauthClients.get(oauthClients.size() - 1);
    OauthClientCursor cr = this.cursor.withSinceUid(last.getUid()).withLimit(limit);
    return gateway.apply(this.filter, cr);
  }
}
